// Monta o corpo da Cloud API: texto simples ou mensagem interativa com até 3 botões.
// Os limites (20 caracteres no título, 1024 no corpo) já vêm aplicados pela API do Sócio; aqui só corta por garantia.
const out = [];
for (const item of $input.all()) {
  const { to, text, buttons } = item.json;
  if (!/^[1-9]\d{9,14}$/.test(String(to))) continue;
  const body = Array.isArray(buttons) && buttons.length > 0
    ? {
        messaging_product: 'whatsapp',
        to,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: { text: String(text).slice(0, 1024) },
          action: {
            buttons: buttons.slice(0, 3).map((b) => ({
              type: 'reply',
              reply: { id: String(b.id).slice(0, 256), title: String(b.title).slice(0, 20) },
            })),
          },
        },
      }
    : { messaging_product: 'whatsapp', to, type: 'text', text: { body: String(text).slice(0, 4096) } };
  out.push({ json: { body } });
}
return out;
